//go:build !js

package sobject_world_engine_test

import (
	"bytes"
	"testing"
	"time"

	sobject_world_engine "github.com/s4wave/spacewave/core/sobject/world/engine"
	"github.com/s4wave/spacewave/db/block"
	block_mock "github.com/s4wave/spacewave/db/block/mock"
	"github.com/s4wave/spacewave/db/unixfs"
	unixfs_world "github.com/s4wave/spacewave/db/unixfs/world"
	"github.com/s4wave/spacewave/db/world"
)

// TestPayloadReusesKeptPages publishes a staged filesystem that reuses metadata
// generated by an earlier operation. A peer must read the whole payload from
// physical storage without access to the author's kept World pages.
func TestPayloadReusesKeptPages(t *testing.T) {
	// Start the real provider and enable the filesystem operations on its World.
	ctx := t.Context()
	w, so := startGatedWorld(t, t.TempDir(), nil)
	lookup := world.NewSchema(unixfs_world.UnixfsTypes).LookupOp
	so.ctrl.SetOpTypes(sobject_world_engine.OpTypes{Lookup: lookup})
	ws := world.NewEngineWorldState(w.eng, true)
	const key = "files"
	fsType := unixfs_world.FSType_FSType_FS_NODE
	if _, _, err := unixfs_world.FsInit(ctx, ws, "", key, fsType, nil, false, time.Now()); err != nil {
		t.Fatal(err)
	}

	// Build a file inside a World operation, as the single-file upload does.
	obj, err := world.MustGetObject(ctx, ws, key)
	if err != nil {
		t.Fatal(err)
	}
	defer world.ReleaseObjectState(obj)
	guide := []byte("a starter file whose filesystem metadata is computed by replay")
	if _, _, err := unixfs_world.FsMknodWithContent(ctx, ws, obj, "", fsType, []string{"guide.md"}, unixfs.NewFSCursorNodeType_File(), int64(len(guide)), bytes.NewReader(guide), 0o644, time.Now()); err != nil {
		t.Fatal(err)
	}

	// Merge a staged batch onto that filesystem, reusing its existing entries.
	writer := unixfs_world.NewBatchFSWriter(ws, key, fsType, "")
	defer writer.Release()
	data := []byte("a second uploaded file")
	if err := writer.AddFile(ctx, nil, "paired.md", unixfs.NewFSCursorNodeType_File(), int64(len(data)), bytes.NewReader(data), 0o644, time.Now()); err != nil {
		t.Fatal(err)
	}
	if err := writer.Commit(ctx); err != nil {
		t.Fatal(err)
	}
	writer.Release()

	// Obtain the accepted graph without reading any derived object metadata.
	states, release, err := so.AccessSharedObjectState(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer release()
	snapshot, err := states.WaitValue(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	span, root, err := sobject_world_engine.PublishedGraph(ctx, snapshot, lookup)
	if err != nil {
		t.Fatal(err)
	}
	if span != nil {
		if _, err := so.GetBlockStore().PutBlockBatch(ctx, []*block.PutBatchEntry{span}); err != nil {
			t.Fatal(err)
		}
	}

	// A fresh peer reads the advertisement through physical storage alone.
	if err := block.CopyGraph(ctx, so.GetBlockStore(), block_mock.NewMockStore(0), root, nil); err != nil {
		t.Fatalf("published payload graph is incomplete: %v", err)
	}

	// Exercise a single staged put with a fresh engine-only filesystem root.
	later := []byte("another operation generates new filesystem metadata")
	if _, _, err := unixfs_world.FsMknodWithContent(ctx, ws, obj, "", fsType, []string{"later.md"}, unixfs.NewFSCursorNodeType_File(), int64(len(later)), bytes.NewReader(later), 0o644, time.Now()); err != nil {
		t.Fatal(err)
	}
	rootRef, _, err := obj.GetRootRef(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stage, err := ws.StageWorldState(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer stage.Release()
	cursor, err := stage.BuildStorageCursor(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer cursor.Release()

	// Keep the selected hash, forced ref and Sync fence of the single put.
	parentData := []byte("staged parent of the current filesystem")
	parentRef, err := block.BuildBlockRef(parentData, nil)
	if err != nil {
		t.Fatal(err)
	}
	putOpts := &block.PutOpts{ForceBlockRef: parentRef, Refs: []*block.BlockRef{rootRef.GetRootRef()}, RefsKnown: true, Sync: true}
	for range 2 {
		got, _, err := cursor.GetBlockStore().PutBlock(ctx, parentData, putOpts)
		if err != nil || !got.EqualsRef(parentRef) {
			t.Fatalf("staged single put: ref=%v err=%v", got, err)
		}
	}

	// The stage owns a physically complete graph even before adoption.
	if err := block.CopyGraph(ctx, so.GetBlockStore(), block_mock.NewMockStore(0), parentRef, nil); err != nil {
		t.Fatalf("staged single-put graph is incomplete: %v", err)
	}
}
